137  /** 从磁盘读取并校验配置，错误信息不含 YAML 原文。 */
138  function readConfig(file: string): ConfigSnapshot {
139    //M 启动和重读共用同一份入口校验。
140    const yamlText = fs.readFileSync(file, 'utf8');
141    const document = yaml.parseDocument(yamlText);
142  
143    //G YAML 解析错误会带出原文，错误里只保留行号。
144    const broken = document.errors[0];
145    if (broken !== undefined) {
146      const line = String(broken.linePos?.[0].line ?? '?');
147      throw new Error(`config.yaml 不是合法的 YAML（第 ${line} 行附近）`);
148    }
149  
150    const written: unknown = document.toJSON();
151    //M 交给 checkConfig 校验一次。顶层确认是对象后，插件仍可读取原始值。
152    const config = checks.checkConfig(written);
153    const raw = written as Record<string, unknown>;
154    return { config, raw };
155  }
156  
157  
```

### 解释
- L140：读 config.yaml 原文。
- L144–L148：守卫：YAML 解析错误会带出原文，错误里只保留行号。
- L152：**外部入口**：交给 checkConfig 校验一次，之后内部直接用。
- L154：校验后的配置和原始对象一起交回。

