274    /** 监听 config.yaml，合并保存动作产生的多次文件通知。 */
275    private watchConfig(file: string): void {
276      this.ctx.effect(() => {
277        let pending: ReturnType<typeof setTimeout> | undefined;
278        //M 非持久监听与定时器让命令行模式能照常退出。
279        const watcher = fs.watch(this.root, { persistent: false }, (_event, name) => {
280          if (name !== null && name.toLowerCase() !== CONFIG_FILE) return;
281  
282          clearTimeout(pending);
283          pending = setTimeout(() => this.reloadConfig(file), CONFIG_RELOAD_DELAY_MS);
284          pending.unref();
285        });
286        watcher.on('error', (error) => {
287          console.error(`config.yaml 监听失败：${error.message}`);
288        });
289        return () => {
290          clearTimeout(pending);
291          watcher.close();
292        };
293      });
294    }
295  
```

### 解释
- L279：监听父目录（设置页用临时文件原子替换后仍能继续监听）；非持久监听让命令行模式能照常退出。
- L280：守卫：不是 config.yaml 的改动不管。
- L283：防抖：500 毫秒后才调重读。
- L291：服务被拔掉时收掉监听和定时器。

