296    /** 校验并应用新快照，失败时继续使用原配置。 */
297    private reloadConfig(file: string): void {
298      try {
299        const next = readConfig(file);
300        //G 一次保存可能产生多次文件通知，内容相同就沿用当前快照。
301        if (util.isDeepStrictEqual(this.raw, next.raw)) return;
302  
303        //M 先更新 pi 的供应商，再让下次读取拿到新快照。
304        this.updateProviders(next.config.providers, this.config.providers);
305        this.current = next;
306      } catch (error) {
307        const reason = textModule.getErrorMessage(error);
308        console.error(`config.yaml 重读失败，继续使用原配置：${reason}`);
309      }
310    }
311  
```

### 解释
- L299：读磁盘上的配置并校验。
- L301：整份原始配置内容相同就沿用当前快照。
- L304–L305：先更新 pi 的供应商，再换快照。
- L306–L309：重读失败只打一行错误，继续用原配置。

