352     * @param name 供应商名/模型 ID。
353     * @returns Sessions.chat() 用的 pi-ai `Model<Api>`，是一份可发对话请求的模型定义。
354     * - `id` 是供应商中的模型标识。
355     * - `provider` 是供应商标识。
356     * - `baseUrl` 是接口地址。
357     * - `api` 是接口适配器标识。`Api` 包含已知标识和扩展字符串。
358     *   jmbots 在这里用 `'openai-completions'`、`'openai-responses'` 或 `'anthropic-messages'`。
359     * - `input` 列出支持的输入模态，元素为 `'text'` 或 `'image'`。
360     * - `reasoning` 表示模型是否支持思考。
361     * - `thinkingLevelMap` 保存配置或 pi 内置的档位映射。
362     * - `contextWindow` 是上下文 token 窗口。
363     * - `maxTokens` 是模型声明的输出 token 上限。
364     * - `cost` 是输入、输出和缓存的计费单价。
365     * 全部字段见 node_modules/@earendil-works/pi-ai/dist/types.d.ts:643，`BaseModel` 与 `Api` 见同文件 630、21 行。
366     * @throws 供应商不在配置里时抛错。
367     */
368    getModel(name: string): piAi.Model<piAi.Api> {
369      //M 第一个斜杠前是供应商名，后面是模型 ID（模型 ID 自己也可以带斜杠）。
370      const slash = name.indexOf('/');
371      const providerName = name.slice(0, slash);
372      const id = name.slice(slash + 1);
373  
374      //G 供应商不在配置里 → 抛错。
375      const provider = this.config.providers[providerName];
376      if (provider === undefined) {
377        throw new Error(`模型 ${name} 的供应商不在 config.yaml 的 providers 里`);
378      }
379  
380      /** 经过校验的模型字段，未手写的模型先取保守值。 */
381      const written = provider.models[id] ?? checks.MODEL_DEFAULTS;
382      //M 兼容设置：供应商的 compat，再盖上这个模型自己的 model_compat。
383      const compat = { ...provider.compat, ...provider.modelCompat[id] };
384  
385      //M 拼成 pi 的模型对象；骨架不算费用，cost 都写 0。
386      const model = {
387        id,
388        name: id,
389        provider: providerName,
390        baseUrl: provider.baseUrl,
391        api: provider.api,
392        cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
393        compat,
394        ...written,
395      } as piAi.Model<piAi.Api>;
396  
397      //G 先用已校验的配置覆盖映射。
398      if (model.thinkingLevelMap !== undefined) return model;
399  
400      //M 同一供应商、模型和协议才沿用 pi 内置映射，保持配置的请求地址与其他设置。
401      const builtinProviders = piCatalog.getBuiltinProviders();
402      const builtinProvider = builtinProviders.find((item) => item === providerName);
403      if (builtinProvider === undefined) return model;
404  
405      const builtinModels: piAi.Model<piAi.Api>[] = piCatalog.getBuiltinModels(builtinProvider);
406      const builtin = builtinModels.find((item) => item.id === id && item.api === provider.api);
407      if (builtin?.thinkingLevelMap === undefined) return model;
408  
409      model.thinkingLevelMap = { ...builtin.thinkingLevelMap };
410      model.reasoning = builtin.reasoning;
411      return model;
412    }
413  }
```

